        Span<byte> nameBytes = nameSize <= 512 ? stackalloc byte[512] : new byte[nameSize];
        nameBytes[System.Text.Encoding.UTF8.GetBytes(nameText, nameBytes)] = 0;
        fixed (byte* namePtr = nameBytes)
        {
            ComponentId resultOut = default;
            NativeResult.ThrowIfFailed(DrainRaised(Handle->find_type(Handle, (sbyte*)namePtr, &resultOut)), "find_type");
            return resultOut;
        }
    }

    /// <summary>The id of the component registered under name, an engine component named by its `KE_COMPONENT_NAME_*` constant or one the game registered.</summary>
    /// <returns>Receives the id; KE_COMPONENT_INVALID when none has the name.</returns>
    /// <exception cref="Exception">The native call failed.</exception>
    public ComponentId FindComponent(string name)
    {
        var nameText = name ?? "";
        var nameSize = System.Text.Encoding.UTF8.GetMaxByteCount(nameText.Length) + 1;
        Span<byte> nameBytes = nameSize <= 512 ? stackalloc byte[512] : new byte[nameSize];
        nameBytes[System.Text.Encoding.UTF8.GetBytes(nameText, nameBytes)] = 0;
        fixed (byte* namePtr = nameBytes)
        {
            ComponentId resultOut = default;
            NativeResult.ThrowIfFailed(DrainRaised(Handle->find_component(Handle, (sbyte*)namePtr, &resultOut)), "find_component");
            return resultOut;
        }
    }

    /// <summary>The bytes a node of type is born with in component.</summary>
    /// <returns>The component's registered size of bytes, valid while the node types live; NULL when the type was never registered or does not carry the component.</returns>
    public nint Initial(ComponentId type, ComponentId component)
    {
        return (nint)Handle->initial(Handle, type, component);
    }

    /// <summary>Whether a node of type carries component: its fields or one its type names in `with`.</summary>
    /// <returns>false for a type never registered.</returns>
    public bool Carries(ComponentId type, ComponentId component)
    {
        return Handle->carries(Handle, type, component);
    }

    /// <summary>Releases the native nodetypes.</summary>
    public void Dispose()
    {
        OnDispose();
        if (_native == null) return;
        _native = null;
        if (_owner is not null)
        {
            _owner.Dispose();
            return;
        }
        foreach (var retained in _retainedUserData.Values) retained.Free();
        _retainedUserData.Clear();
        foreach (var held in _held) held.DangerousRelease();
        _held.Clear();
    }

    /// <summary>Destroys the native nodetypes once its last reference is released, then releases what it held.</summary>
    private void Teardown()
    {
        foreach (var retained in _retainedUserData.Values) retained.Free();
        _retainedUserData.Clear();
        _destroy(_owned);
        foreach (var held in _held) held.DangerousRelease();
        _held.Clear();
    }

    partial void OnDispose();

    /// <summary>What retained handlers threw and no call has reported yet, from any thread the native side ran them on.</summary>
    private static readonly System.Collections.Concurrent.ConcurrentQueue<Exception> s_raisedCallbackFailures = new();

    /// <summary>Throws what retained handlers raised, or returns <paramref name="code"/> when they raised nothing.</summary>
    private static T DrainRaised<T>(T code)
    {
        var collected = new List<Exception>();
        while (s_raisedCallbackFailures.TryDequeue(out var failure)) collected.Add(failure);
        if (collected.Count == 0) return code;
        throw new InvalidOperationException("A handler registered with this provider threw",
            collected.Count == 1 ? collected[0] : new AggregateException(collected));
    }
}
